    /// <summary>
    /// Core implementation of ITypeExtended for FHIR type metadata with extended properties.
    /// </summary>
    private sealed class CoreType : Ignixa.Abstractions.ITypeExtended
    {
        private readonly Func<IReadOnlyList<Ignixa.Abstractions.IType>>? _childrenFactory;
        private IReadOnlyList<Ignixa.Abstractions.IType>? _children;

        public CoreType(
            string name,
            Ignixa.Abstractions.FhirPrimitive primitive,
            bool isResource,
            bool isAbstract,
            bool isChoiceElement,
            bool isModifier,
            bool isCollection,
            bool isRequired,
            bool inSummary,
            int order,
            Func<IReadOnlyList<Ignixa.Abstractions.IType>>? childrenFactory,
            int? min = null,
            string? max = null,
            IReadOnlyList<Ignixa.Abstractions.IConstraint>? constraints = null,
            Ignixa.Abstractions.IBinding? binding = null,
            object? fixedValue = null,
            object? patternValue = null,
            IReadOnlyList<Ignixa.Abstractions.ITypeReference>? types = null,
            string? defaultTypeName = null,
            IReadOnlyList<string>? referenceTargets = null,
            string? contentReference = null,
            Ignixa.Abstractions.SlicingMetadata? slicing = null)
        {
            Info = new Ignixa.Abstractions.TypeInfo(name, primitive, isResource, isAbstract, isChoiceElement, isModifier);
            IsCollection = isCollection;
            IsRequired = isRequired;
            InSummary = inSummary;
            Order = order;
            _childrenFactory = childrenFactory;
            Min = min ?? 0;
            Max = max ?? "*";
            Constraints = constraints ?? Array.Empty<Ignixa.Abstractions.IConstraint>();
            Binding = binding;
            FixedValue = fixedValue;
            PatternValue = patternValue;
            Types = types ?? (defaultTypeName != null ? new[] { new Ignixa.Abstractions.TypeReferenceDefinition(defaultTypeName) } : new[] { new Ignixa.Abstractions.TypeReferenceDefinition(name) });
            DefaultTypeName = defaultTypeName;
            ReferenceTargets = referenceTargets ?? Array.Empty<string>();
            ContentReference = contentReference;
            Slicing = slicing;
        }

        // IType properties
        public Ignixa.Abstractions.TypeInfo Info { get; }
        public bool IsCollection { get; }
        public bool IsRequired { get; }
        public bool InSummary { get; }
        public int Order { get; }

        public IReadOnlyList<Ignixa.Abstractions.IType> Children
        {
            get
            {
                if (_children == null)
                {
                    _children = _childrenFactory?.Invoke() ?? Array.Empty<Ignixa.Abstractions.IType>();
                }
                return _children;
            }
        }

        // ITypeExtended properties
        public int Min { get; }
        public string Max { get; }
        public IReadOnlyList<Ignixa.Abstractions.IConstraint> Constraints { get; }
        public Ignixa.Abstractions.IBinding? Binding { get; }
        public object? FixedValue { get; }
        public object? PatternValue { get; }
        public IReadOnlyList<Ignixa.Abstractions.ITypeReference> Types { get; }
        public string? DefaultTypeName { get; }
        public IReadOnlyList<string> ReferenceTargets { get; }
        public string? ContentReference { get; }
        public Ignixa.Abstractions.SlicingMetadata? Slicing { get; }
    }
